            type: "select",
            options: (() => {
              return this.accountsPayable.map((data) => {
                return {
                  value: data.sas_id,
                  label: locale == "ar" ? data.sas_name : data.sas_name_en,
                };
              });
            })(),
            label: "agents.payable_account",
          },
          {
            model: "prepayments_subaccount_id",
            type: "select",
            options: (() => {
              return this.advancedPayments.map((data) => {
                return {
                  value: data.sas_id,
                  label: locale == "ar" ? data.sas_name : data.sas_name_en,
                };
              });
