      //         });
    },
    deleteAgent(app) {
      var data = {
        title: "popups.delete",
        msg: "popups.deletemsg",
      };
      this.popup.confirm(data).then((res) => {
        if (res) {
          this.http.delete("agents", app.id).then(() => {
            this.get(this.page);
          });
        }
      });
    },
    search() {
      this.searchMode = true;
      this.tot_pages = 0;
      this.http
        .post("agents/search", {
          search: this.searchModel,
          limit: this.limit,
          page: this.page,
          col: "name",
        })
        .then((res) => {
          this.agents = res.data;
          this.agents.forEach((agent, index) => {
            let code = (this.page - 1) * this.limit + index + 1;
            agent.code =
              "SUP-" +
              (code < 10
                ? "000" + code
                : code < 100
                ? "00" + code
                : code < 1000
                ? "0" + code
                : code);
          });
        });
    },
    cancelSearchMode() {
      this.searchModel = "";
      this.searchMode = false;
      this.get(this.page);
    },
    getAccounts() {
      this.http.get("agents/accounts/subledger").then((res) => {
        if (res.status) {
          this.accountsPayable = res.data[0]?.sub_accounts;
          this.advancedPayments = res.data[1]?.sub_accounts;
        }
      });
    },
    get(page) {
      console.log(page);
      this.http
        .post("agents/pagination", {
          limit: this.limit,
          page: page,
          id: parseInt(this.$route.params.id),
        })
        .then((res) => {
          this.page = page;
          this.tot_pages = Math.ceil(res.tot / this.limit);
          this.agents = res.data;
          this.agents.forEach((agent, index) => {
            let code = (this.page - 1) * this.limit + index + 1;
            agent.code =
              "SUP-" +
              (code < 10
                ? "000" + code
                : code < 100
                ? "00" + code
                : code < 1000
                ? "0" + code
                : code);
          });
        });
    },
    nextStep() {
      if (this.currentStep < this.circlesCount) {
        this.currentStep++;
        this.tryNext = false;
      }
    },
    prevStep() {
      if (this.currentStep > 1) {
        this.currentStep--;
      }
    },
    handelEdit(agent) {
      this.form = {
        ...agent,
        payable: agent.payable || { enabled: false, value: 0 },
        prepayment: agent.prepayment || { enabled: false, value: 0 },
      };
      this.secondModal = true;
      this.currentStep = 1;
    },
    handleSelectChange() {
      // Reset both
      this.form.prepayment.enabled = false;
      this.form.payable.enabled = false;

      // Enable the selected one
      if (this.form.selectedOption === "prepayment") {
        this.form.prepayment.enabled = true;
      } else if (this.form.selectedOption === "payable") {
        this.form.payable.enabled = true;
      }
    },
  },
  created() {
    this.get(1);
    this.getAccounts();
  },
};
</script>

